{
    public static readonly BindableProperty CheckedColorProperty = BindableProperty.Create(nameof(CheckedColor), typeof(Color), typeof(CustomRadioButton), Color.Default);
    public static readonly BindableProperty UncheckedColorProperty = BindableProperty.Create(nameof(UncheckedColor), typeof(Color), typeof(CustomRadioButton), Color.Default);

    public Color CheckedColor
    {
        get { return (Color)GetValue(CheckedColorProperty); }
        set { SetValue(CheckedColorProperty, value); }
    }

    public Color UncheckedColor
    {
        get { return (Color)GetValue(UncheckedColorProperty); }
        set { SetValue(UncheckedColorProperty, value); }
    }
}
