import "https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v4.4.2/contracts/utils/Counters.sol";

contract MyNFTCollection is ERC721URIStorage {
    using Counters for Counters.Counter;
    Counters.Counter private _tokenIds;

    // Mapping of token IDs to their owners
    mapping (uint256 => address) public tokenOwners;

    // Mapping of token IDs to their metadata
    mapping (uint256 => string) public tokenMetadata;

    // Maximum supply of NFTs
    uint256 public constant MAX_SUPPLY = 1000;

    constructor() ERC721("My NFT Collection", "MNC") {
        // Initialize the token ID counter
        _tokenIds.initialize();
    }

    // Function to mint a new NFT
    function mintNFT(address _to, string memory _tokenURI) public {
        // Check if the maximum supply has been reached
        require(_tokenIds.current() < MAX_SUPPLY, "Maximum supply reached");

        // Mint the NFT
        _mint(_to, _tokenIds.current());
        _tokenOwners[_tokenIds.current()] = _to;
        tokenMetadata[_tokenIds.current()] = _tokenURI;

        // Increment the token ID counter
        _tokenIds.increment();
    }

    // Function to get the metadata of a token
    function getTokenMetadata(uint256 _tokenId) public view returns (string memory) {
        return tokenMetadata[_tokenId];
    }
}
```

**Explanation:**

*   We import the necessary OpenZeppelin contracts for ERC721 and Counters.
*   We define a contract `MyNFTCollection` that inherits from `ERC721URIStorage`.
*   We use the `Counters` library to keep track of the token IDs.
*   We define a mapping of token IDs to their owners and metadata.
*   We set a maximum supply of NFTs.
*   The `mintNFT` function allows users to mint new NFTs, checking if the maximum supply has been reached before minting.
*   The `getTokenMetadata` function returns the metadata of a specific token.

**Note:** This is a basic example and you should consider adding additional functionality, such as:

*   Access control (e.g., only allow certain addresses to mint NFTs)
*   Royalty management
*   Token burning
*   Events for tracking minting and transfers
*   Security audits and testing

**Type Literal Combinations in TypeScript**
=====================================

Type literal combinations in TypeScript allow you to create complex types by combining existing types using various operators. This feature is useful for creating more expressive and readable type definitions.

**Basic Type Combinations**
---------------------------

### Union Types

Union types allow you to specify a value that can be one of several types.

```typescript
type StringOrNumber = string | number;
```

In this example, `StringOrNumber` can be either a string or a number.

### Intersection Types

Intersection types allow you to specify a value that must be of multiple types.

```typescript
type Person = { name: string } & { age: number };
```

In this example, `Person` must have both a `name` property of type `string` and an `age` property of type `number`.

### Type Guards

Type guards are used to narrow the type of a value within a specific scope.

```typescript
function isString<T>(value: T): value is string {
  return typeof value === 'string';
}

function processString(s: string) {
  console.log(s.length);
}

function processNumber(n: number) {
  console.log(n.toFixed(2));
}

const value = 'hello';

if (isString(value)) {
  processString(value); // OK
} else {
  processNumber(value); // Error: Type 'string' is not assignable to parameter of type 'number'.
}
```

